options = [
    {'name':'Запуск продукта','prob':.6,'gain':500000,'loss':200000},
    {'name':'Реклама','prob':.8,'gain':150000,'loss':50000}
]
def expected_value(option):
    p,gain,loss = option['prob'],option['gain'],option['loss']
    if not 0 <= p <= 1 or gain < 0 or loss < 0:
        raise ValueError('Некорректная вероятность или сумма')
    return p*gain-(1-p)*loss

print('Вариант | EV | риск')
for option in options:
    option['ev'] = expected_value(option)
    print(f"{option['name']} | {option['ev']:.0f} | {option['loss']}")
best = max(options, key=lambda option: option['ev'])
print('Рекомендация по EV:', best['name'])
if all(option['ev'] < 0 for option in options):
    print('Внимание: EV обоих вариантов отрицательно')
